//! Canonical fieldset identity and readonly form/type metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=fieldset name=group><legend>Group</legend><input value=seed></fieldset></form><form id=other></form><fieldset id=external form=other></fieldset></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn fieldset_validity_canonical_same_object_and_live_custom_flags(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),P=HTMLFieldSetElement.prototype,a=Object.getOwnPropertyDescriptor(P,'validity'),set=P.setCustomValidity;if(!a||typeof a.get!=='function'||a.set!==undefined||typeof set!=='function'||set.length!==1||set.name!=='setCustomValidity')throw 'canonical validity entries';var v=x.validity;if(!(v instanceof ValidityState)||v!==x.validity||v!==a.get.call(x)||v.customError!==false||v.valid!==true)throw 'live initial validity';x.setCustomValidity('error');if(v.customError!==true||v.valid!==false||x.validity!==v||x.willValidate!==false||x.validationMessage!==''||x.checkValidity()!==true||x.reportValidity()!==true)throw 'custom error independent of noncandidate';x.setCustomValidity('');if(v.customError!==false||v.valid!==true)throw 'live cleared custom error';"#);}
#[test]
fn fieldset_validity_inert_clone_fresh_adoption_preserves_error(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','fieldset');if(typeof x.setCustomValidity!=='function')throw 'canonical custom validity';x.setCustomValidity('a\ud800\r\nb\udfff');var v=x.validity,c=x.cloneNode(false),other=new Document();if(v.customError!==true||v.valid!==false||c.validity.customError!==false||c.validity.valid!==true||c.validity===v)throw 'fresh clone validity';if(other.adoptNode(x)!==x||x.validity!==v||!v.customError)throw 'adopted live validity';x.setCustomValidity('');if(!v.valid||v.customError)throw 'adopted clear';"#);}
#[test]
fn fieldset_validity_converts_once_and_rejects_wrong_concrete_getters(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),P=HTMLFieldSetElement.prototype,calls=0;if(typeof P.setCustomValidity!=='function')throw 'canonical custom setter';P.setCustomValidity.call(x,{toString:function(){calls++;return 'a\ud800\r\nb\udfff';}});if(calls!==1||!x.validity.customError)throw 'exact single conversion';var output=document.createElement('output'),og=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'validity').get,fg=Object.getOwnPropertyDescriptor(P,'validity').get;for(var pair of [[og,x],[fg,output],[HTMLOutputElement.prototype.setCustomValidity,x],[P.setCustomValidity,output]]){var caught=false;try{pair[0].call(pair[1],{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'concrete validity interface';}if(calls!==1)throw 'brand before conversion';"#);}

#[test]
fn fieldset_validity_canonical_readonly_descriptors_brands_and_required_argument(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('fieldset'),v=o.validity,p=HTMLFieldSetElement.prototype,a=Object.getOwnPropertyDescriptor(p,'validity'),method=p.setCustomValidity;if(!a.enumerable||!a.configurable||a.set!==undefined||a.get.name!=='get validity'||a.get.length!==0||method.name!=='setCustomValidity'||method.length!==1||Object.hasOwn(o,'validity'))throw 'output validity descriptor';var keys=['valueMissing','typeMismatch','patternMismatch','tooLong','tooShort','rangeUnderflow','rangeOverflow','stepMismatch','badInput','customError','valid'];for(var key of keys){var descriptor=Object.getOwnPropertyDescriptor(ValidityState.prototype,key);if(!descriptor||!descriptor.enumerable||!descriptor.configurable||descriptor.set!==undefined||descriptor.get.name!=='get '+key||descriptor.get.length!==0||Object.hasOwn(v,key))throw 'readonly validity flags';var expected=key==='valid';v[key]='author';var caught=false;try{(function(){'use strict';v[key]='author';})();}catch(e){caught=e instanceof TypeError;}if(!caught||v[key]!==expected||Object.hasOwn(v,key))throw 'readonly validity assignment';for(var bad of [{},Object.create(ValidityState.prototype),o,document.createElement('input'),document.createElement('output').htmlFor]){caught=false;try{descriptor.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine validity brand';}}var caught=false;try{new ValidityState();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal validity constructor';var calls=0;for(var bad of [null,{},v,Object.create(p),document.createElement('input')]){caught=false;try{method.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'method brand before conversion';}o.setCustomValidity('existing');caught=false;try{o.setCustomValidity();}catch(e){caught=e instanceof TypeError;}if(!caught||v.customError!==true)throw 'required custom error argument';"#);}
#[test]
fn fieldset_validity_author_shadows_restore_and_saved_native_views(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('fieldset'),v=o.validity,proto=HTMLFieldSetElement.prototype,a=Object.getOwnPropertyDescriptor(proto,'validity'),setter=proto.setCustomValidity,valid=Object.getOwnPropertyDescriptor(ValidityState.prototype,'valid');Object.defineProperty(o,'validity',{value:'own',configurable:true});o.setCustomValidity='author';if(o.validity!=='own'||a.get.call(o)!==v)throw 'own validity shadow';setter.call(o,'error');if(valid.get.call(v)!==false)throw 'native custom authority';delete o.validity;delete o.setCustomValidity;Object.defineProperty(ValidityState.prototype,'valid',{value:'prototype',configurable:true});if(v.valid!=='prototype'||valid.get.call(v)!==false)throw 'prototype flag shadow';delete ValidityState.prototype.valid;if(v.valid!==undefined||valid.get.call(v)!==false)throw 'deleted flag';Object.defineProperty(ValidityState.prototype,'valid',valid);Object.defineProperty(v,'customError',{value:'own',configurable:true});setter.call(o,'');if(v.valid!==true||v.customError!=='own')throw 'native flag independence';delete v.customError;if(v.customError!==false||o.validity!==v)throw 'restored native state';"#);}
#[test]
fn fieldset_validity_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('fieldset'),v=o.validity,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var proto=frame.contentWindow.HTMLFieldSetElement.prototype,get=Object.getOwnPropertyDescriptor(proto,'validity').get,set=proto.setCustomValidity,valid=Object.getOwnPropertyDescriptor(frame.contentWindow.ValidityState.prototype,'valid').get,calls=0;set.call(o,'custom');if(get.call(o)!==v||valid.call(v)!==false)throw 'child canonical state';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_custom_errors.len());p.set_location(&crate::navigation::address("https://foreign-output-validity.test/",&crate::navigation::Location::home()).unwrap());for source in ["get.call(o);","valid.call(v);","set.call(o,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_custom_errors.len()),state);}p.set_location(&crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||valid.call(v)!==false)throw 'origin before conversion';set.call(o,'');if(valid.call(v)!==true||get.call(o)!==v)throw 'fresh validity recovery';");}
#[test]
fn fieldset_validity_exact_normalized_native_storage_and_clear(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('fieldset');o.setCustomValidity('A\ud800z\r\nB\rC\0\udfff');"#);let n=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="fieldset")).unwrap();let object=node_handle(n);let value=p.state.output_custom_errors.get(&object).unwrap();assert_eq!(value.code_units().collect::<Vec<_>>(),vec![65,0xd800,122,10,66,10,67,0,0xdfff]);let old=value.capacity();let retained=p.state.retained;run(&mut d,&mut f,&mut p,"o.setCustomValidity('');if(o.validity.customError!==false||o.validity.valid!==true)throw 'empty clear';");assert!(p.state.output_custom_errors.get(&object).is_none());assert_eq!(p.state.retained,retained-old);}
#[test]
fn fieldset_validity_writer_limits_preserve_authority_and_recover(){for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var doc=document.implementation.createHTMLDocument('inert'),o=doc.createElement('fieldset');o.name='current';o.setCustomValidity('existing');var v=o.validity;"}else{"var o=document.getElementById('fieldset');o.name='current';o.setCustomValidity('existing');var v=o.validity;"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len(),p.state.output_custom_errors.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(r#"o.setCustomValidity('new A\ud800z\r\nB\udfff');"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len(),p.state.output_custom_errors.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(o.validity!==v||v.customError!==true||v.valid!==false||o.name!=='current')throw 'atomic custom error refusal';o.setCustomValidity('');if(v.valid!==true||v.customError!==false)throw 'fresh custom error recovery';");}}}

#[test]
fn fieldset_validity_first_index_growth_refuses_joint_peak_and_recovers(){for prior in [0,4]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var doc=document.implementation.createHTMLDocument('source'),outs=[];for(var i=0;i<{prior};i++){{var x=doc.createElement('fieldset');x.setCustomValidity('seed');outs.push(x);}}var o=doc.createElement('fieldset'),v=o.validity;"));p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_custom_errors.len(),p.state.output_custom_errors.storage_bytes());let limit=p.state.retained_limit;p.state.retained_limit=p.state.retained+8;p.begin_job();let error=p.runtime.execute("o.setCustomValidity('next');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("storage")||error.contains("allowance"),"{prior}: {error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_custom_errors.len(),p.state.output_custom_errors.storage_bytes()),state);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(o.validity!==v||v.valid!==true||v.customError!==false)throw 'unpublished native error';for(var x of outs)if(x.validity.customError!==true||x.validity.valid!==false)throw 'existing errors changed';o.setCustomValidity('next');if(v.customError!==true||v.valid!==false)throw 'fresh native error index recovery';");assert_eq!(p.state.output_custom_errors.len(),prior+1);}}

#[test]
fn fieldset_validity_shared_error_index_keeps_concrete_owners_independent(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),output=document.createElement('output'),xv=x.validity,ov=output.validity;x.setCustomValidity('field');output.setCustomValidity('out');if(xv===ov||!xv.customError||!ov.customError||xv.valid||ov.valid)throw 'independent native validity handles';x.setCustomValidity('');if(xv.customError||!xv.valid||!ov.customError||ov.valid)throw 'clearing actual owner only';x.setCustomValidity('field');output.setCustomValidity('');if(!xv.customError||xv.valid||ov.customError||!ov.valid)throw 'reverse owner isolation';"#);assert_eq!(p.state.output_custom_errors.len(),1);}

#[test]
fn fieldset_validity_conversion_abrupt_and_non_candidate_events(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('fieldset'),v=o.validity,count=0,invalid=0;o.addEventListener('invalid',function(){invalid++;});o.setCustomValidity({toString:function(){count++;o.name='current';return 'error';}});if(count!==1||v.customError!==true||o.name!=='current'||o.type!=='fieldset')throw 'once conversion';var caught=false;try{o.setCustomValidity({toString:function(){throw 'abrupt';}});}catch(e){caught=e==='abrupt';}if(!caught||v.valid!==false)throw 'abrupt custom error';caught=false;try{o.setCustomValidity(Symbol());}catch(e){caught=e instanceof TypeError;}if(!caught||v.customError!==true)throw 'symbol custom error';o.setCustomValidity(null);if(v.customError!==true||o.checkValidity()!==true||o.reportValidity()!==true||o.validationMessage!==''||invalid)throw 'noncandidate custom error';o.setCustomValidity('');if(v.valid!==true)throw 'custom recovery';"#);}
